function canCutOut(note: string, magazine: string): boolean {
  if (note.length > magazine.length) return false;
  const count = new Array(26).fill(0);
  for (let i = 0; i < magazine.length; i++) count[magazine.charCodeAt(i) - 97]++;
  for (let i = 0; i < note.length; i++) {
    if (--count[note.charCodeAt(i) - 97] < 0) return false;
  }
  return true;
}

